// Construye la solicitud GraphQL (Admin API) para los puertos catalog, inventory y order_registry
const r = $json;
const s = r.settings || {};
const inp = r.input || {};
const fail = (status, code, message) => ({ json: { skip: true, status, error: { code, message } } });
if (!s.shop_domain || !s.api_version) return fail('PERMANENT_ERROR', 'VALIDATION', 'faltan settings.shop_domain o settings.api_version');
const IMG = 'media(first: 10) { nodes { ... on MediaImage { image { url altText } } } }';
const VAR = 'id sku title price compareAtPrice availableForSale inventoryQuantity selectedOptions { name value } media(first: 1) { nodes { ... on MediaImage { image { url altText } } } }';
const PROD = 'id title handle description productType vendor tags status onlineStoreUrl updatedAt ' + IMG + ' variants(first: 100) { nodes { ' + VAR + ' } }';
const INV = 'id sku availableForSale inventoryQuantity inventoryItem { id inventoryLevels(first: 20) { nodes { location { id name } quantities(names: ["available"]) { name quantity } } } }';
const ORD = 'id name displayFinancialStatus displayFulfillmentStatus cancelledAt createdAt tags totalPriceSet { shopMoney { amount currencyCode } }';
const tag = (n) => 'dalia-' + String(n).replace(/[^A-Za-z0-9_-]/g, '');
let query, variables = {};
const key = r.port + '.' + r.operation;
switch (key) {
  case 'catalog.search_products':
  case 'catalog.list_products_page': {
    let q = inp.query || '';
    if (key === 'catalog.list_products_page' && inp.updated_since) q = (q ? q + ' AND ' : '') + "updated_at:>'" + inp.updated_since + "'";
    query = 'query($n: Int!, $q: String, $after: String) { products(first: $n, query: $q, after: $after) { nodes { ' + PROD + ' } pageInfo { hasNextPage endCursor } } }';
    variables = { n: Math.min(inp.limit || 10, 50), q: q || null, after: inp.cursor || null };
    break;
  }
  case 'catalog.get_product':
    query = 'query($id: ID!) { product(id: $id) { ' + PROD + ' } }';
    variables = { id: inp.product_ref };
    break;
  case 'catalog.get_variants':
    query = 'query($ids: [ID!]!) { nodes(ids: $ids) { ... on ProductVariant { ' + VAR + ' product { id title } } } }';
    variables = { ids: inp.variant_refs || [] };
    break;
  case 'inventory.check_availability':
    query = 'query($ids: [ID!]!) { nodes(ids: $ids) { ... on ProductVariant { ' + INV + ' } } }';
    variables = { ids: inp.variant_refs || [] };
    break;
  case 'inventory.reserve':
  case 'inventory.release':
    return fail('NOT_SUPPORTED', 'NOT_SUPPORTED_BY_PROVIDER', 'Shopify no ofrece reservas de inventario por API en este adaptador; M5 aplica la configuración de su capacidad');
  case 'order_registry.get_order':
    if (inp.external_order_ref) { query = 'query($id: ID!) { order(id: $id) { ' + ORD + ' } }'; variables = { id: inp.external_order_ref }; }
    else { query = 'query($q: String!) { orders(first: 1, query: $q) { nodes { ' + ORD + ' } } }'; variables = { q: 'tag:' + tag(inp.order_number) }; }
    break;
  case 'order_registry.create_order':
    // Paso 1 (idempotencia): buscar si el pedido ya existe por su etiqueta dalia-<order_number>
    if (!inp.order_number || !Array.isArray(inp.lines) || inp.lines.length === 0) return fail('PERMANENT_ERROR', 'VALIDATION', 'create_order requiere order_number y lines');
    query = 'query($q: String!) { orders(first: 1, query: $q) { nodes { ' + ORD + ' } } }';
    variables = { q: 'tag:' + tag(inp.order_number) };
    break;
  case 'order_registry.cancel_order':
    query = 'mutation($id: ID!, $reason: OrderCancelReason!, $note: String) { orderCancel(orderId: $id, reason: $reason, restock: true, notifyCustomer: false, staffNote: $note) { job { id done } orderCancelUserErrors { field message code } } }';
    variables = { id: inp.external_order_ref, reason: inp.reason_code || 'CUSTOMER', note: inp.reason ? String(inp.reason).slice(0, 250) : null };
    break;
  case 'order_registry.mark_paid':
    query = 'mutation($id: ID!) { orderMarkAsPaid(input: { id: $id }) { order { id displayFinancialStatus } userErrors { field message } } }';
    variables = { id: inp.external_order_ref };
    break;
  default:
    return fail('NOT_SUPPORTED', 'OPERATION_NOT_SUPPORTED', key);
}
const url = 'https://' + s.shop_domain + '/admin/api/' + s.api_version + '/graphql.json';
return { json: { skip: false, key, url, payload: { query, variables }, timeout_ms: s.timeout_ms || 10000 } };

// No se obtuvo token de acceso (client credentials). Nada se envió a Shopify: nunca es UNKNOWN.
const res = $json || {};
const code = res.statusCode;
const auth = code === 400 || code === 401 || code === 403;
const msg = res.body?.error_description || res.body?.errors || res.error?.message || res.error || ('HTTP ' + code);
return { json: { status: auth ? 'PERMANENT_ERROR' : 'RETRYABLE_ERROR', data: null, error: { code: auth ? 'AUTH_ERROR' : 'TOKEN_UNAVAILABLE', message: 'no se obtuvo token de Shopify: ' + String(typeof msg === 'object' ? JSON.stringify(msg) : msg).slice(0, 300), http_status: code ?? null } } };

// Normaliza la respuesta de Shopify al contrato de cada puerto.
// Se usa tanto para la primera llamada como para la de creación de pedido.
const req = $('Solicitud del puerto').item.json;
const s = req.settings || {};
const res = $json;
const code = res.statusCode;
const body = res.body || {};
const key = req.port + '.' + req.operation;
const sensitive = req.sensitive === true;
const creating = req.operation === 'create_order' && String($prevNode.name).startsWith('Crear pedido en Shopify');
const errs = Array.isArray(body.errors) ? body.errors : (body.errors ? [{ message: typeof body.errors === 'string' ? body.errors : JSON.stringify(body.errors) }] : []);
if (code === 429 || code >= 500 || errs.some(e => e.extensions?.code === 'THROTTLED')) {
  return { json: { status: (sensitive && creating) || (sensitive && req.operation !== 'create_order') ? 'UNKNOWN' : 'RETRYABLE_ERROR', data: null, error: { code: code >= 500 ? 'HTTP_' + code : 'THROTTLED', message: JSON.stringify(errs).slice(0, 500), http_status: code } } };
}
if (code === 401 || code === 403) {
  return { json: { status: 'PERMANENT_ERROR', data: null, error: { code: 'AUTH_ERROR', message: 'Shopify rechazó la credencial (revise la app, sus permisos o ejecute dalia.int_token_invalidate)', http_status: code } } };
}
if (code < 200 || code >= 300 || errs.length) {
  return { json: { status: 'PERMANENT_ERROR', data: null, error: { code: code >= 300 ? 'HTTP_' + code : 'GRAPHQL_ERROR', message: JSON.stringify(errs.length ? errs : body).slice(0, 500), http_status: code } } };
}
const d = body.data || {};
const cur = s.currency || null;
const img = (m) => ((m && m.nodes) || []).filter(n => n && n.image).map(n => ({ url: n.image.url, alt: n.image.altText || null }));
const variant = (v) => ({ variant_ref: v.id, sku: v.sku || null, title: v.title, price: v.price !== undefined ? Number(v.price) : null, compare_at_price: v.compareAtPrice ? Number(v.compareAtPrice) : null, currency: cur, available: v.availableForSale === true, available_qty: v.inventoryQuantity ?? null, options: Object.fromEntries((v.selectedOptions || []).map(o => [o.name, o.value])), images: img(v.media), product_ref: v.product?.id || null });
const product = (p) => ({ product_ref: p.id, title: p.title, handle: p.handle, description: p.description, product_type: p.productType || null, vendor: p.vendor || null, tags: p.tags || [], status: p.status, url: p.onlineStoreUrl || null, images: img(p.media), variants: ((p.variants && p.variants.nodes) || []).map(variant), updated_at: p.updatedAt });
const order = (o) => o ? ({ external_order_ref: o.id, external_order_name: o.name, financial_status: o.displayFinancialStatus, fulfillment_status: o.displayFulfillmentStatus, cancelled: !!o.cancelledAt, cancelled_at: o.cancelledAt, created_at: o.createdAt, total: o.totalPriceSet ? Number(o.totalPriceSet.shopMoney.amount) : null, currency: o.totalPriceSet?.shopMoney?.currencyCode || null }) : null;
const ok = (data) => ({ json: { status: 'OK', data, error: null } });
switch (key) {
  case 'catalog.search_products':
  case 'catalog.list_products_page':
    return ok({ products: (d.products?.nodes || []).map(product), next_cursor: d.products?.pageInfo?.hasNextPage ? d.products.pageInfo.endCursor : null });
  case 'catalog.get_product':
    return d.product ? ok({ product: product(d.product) }) : { json: { status: 'NOT_FOUND', data: null, error: { code: 'PRODUCT_NOT_FOUND', message: req.input?.product_ref } } };
  case 'catalog.get_variants':
    return ok({ variants: (d.nodes || []).filter(Boolean).map(variant) });
  case 'inventory.check_availability':
    return ok({ items: (d.nodes || []).filter(Boolean).map(v => {
      const locs = (v.inventoryItem?.inventoryLevels?.nodes || []).map(l => ({ location_ref: l.location?.id, name: l.location?.name, available: (l.quantities || []).find(q => q.name === 'available')?.quantity ?? null }));
      const byLoc = s.location_id ? locs.filter(l => l.location_ref === s.location_id) : locs;
      const qty = byLoc.length ? byLoc.reduce((a, l) => a + (l.available || 0), 0) : (v.inventoryQuantity ?? null);
      return { variant_ref: v.id, sku: v.sku || null, available_for_sale: v.availableForSale === true, available_qty: qty, locations: locs };
    }) });
  case 'order_registry.get_order': {
    const o = d.order || (d.orders?.nodes || [])[0];
    return o ? ok(order(o)) : { json: { status: 'NOT_FOUND', data: null, error: { code: 'ORDER_NOT_FOUND', message: 'no existe en Shopify' } } };
  }
  case 'order_registry.create_order': {
    if (!creating) {
      const found = (d.orders?.nodes || [])[0];
      return { json: { status: 'OK', data: found ? Object.assign(order(found), { created: false }) : null, error: null, _needs_create: !found } };
    }
    const r = d.orderCreate || {};
    if ((r.userErrors || []).length) return { json: { status: 'PERMANENT_ERROR', data: null, error: { code: 'USER_ERRORS', message: JSON.stringify(r.userErrors).slice(0, 500) } } };
    return ok({ external_order_ref: r.order.id, external_order_name: r.order.name, created: true });
  }
  case 'order_registry.cancel_order': {
    const r = d.orderCancel || {};
    if ((r.orderCancelUserErrors || []).length) return { json: { status: 'PERMANENT_ERROR', data: null, error: { code: r.orderCancelUserErrors[0].code || 'USER_ERRORS', message: JSON.stringify(r.orderCancelUserErrors).slice(0, 500) } } };
    return ok({ cancel_requested: true, job_ref: r.job?.id || null, job_done: r.job?.done ?? null });
  }
  case 'order_registry.mark_paid': {
    const r = d.orderMarkAsPaid || {};
    if ((r.userErrors || []).length) return { json: { status: 'PERMANENT_ERROR', data: null, error: { code: 'USER_ERRORS', message: JSON.stringify(r.userErrors).slice(0, 500) } } };
    return ok({ external_order_ref: r.order.id, financial_status: r.order.displayFinancialStatus });
  }
}
return { json: { status: 'NOT_SUPPORTED', data: null, error: { code: 'OPERATION_NOT_SUPPORTED', message: key } } };

// Paso 2 de create_order: construir orderCreate si el pedido no existe todavía
const req = $('Solicitud del puerto').item.json;
const s = req.settings || {};
const inp = req.input || {};
const currency = inp.currency || s.currency;
const tag = 'dalia-' + String(inp.order_number).replace(/[^A-Za-z0-9_-]/g, '');
const order = {
  currency,
  lineItems: inp.lines.map(l => ({ variantId: l.variant_ref, quantity: l.qty, priceSet: { shopMoney: { amount: String(l.unit_price), currencyCode: currency } } })),
  tags: ['dalia', tag],
  note: inp.notes || null,
  customAttributes: [{ key: 'dalia_order_number', value: String(inp.order_number) }],
  financialStatus: 'PENDING'
};
if (inp.customer?.email) order.email = inp.customer.email;
if (inp.customer?.phone) order.phone = inp.customer.phone;
if (inp.shipping_address) {
  const a = inp.shipping_address;
  order.shippingAddress = { firstName: a.first_name, lastName: a.last_name || '-', address1: a.address1, address2: a.address2 || null, city: a.city, provinceCode: a.province_code || null, countryCode: a.country_code, zip: a.zip || null, phone: a.phone || inp.customer?.phone || null };
}
const query = 'mutation($order: OrderCreateOrderInput!, $options: OrderCreateOptionsInput) { orderCreate(order: $order, options: $options) { order { id name } userErrors { field message } } }';
const variables = { order, options: { sendReceipt: false, sendFulfillmentReceipt: false, inventoryBehaviour: s.order_inventory_behaviour || 'DECREMENT_OBEYING_POLICY' } };
const url = 'https://' + s.shop_domain + '/admin/api/' + s.api_version + '/graphql.json';
// Token (solo auth_mode = client_credentials): el recién obtenido o el vigente en caché
let token = null;
if (s.auth_mode === 'client_credentials') {
  try { token = $('Guardar token').item.json.tok.token; } catch (e) { token = null; }
  if (!token) { try { token = $('Leer token vigente').item.json.tok.token; } catch (e) { token = null; } }
}
return { json: { auth_mode: s.auth_mode || 'static_token', token, url, payload: { query, variables }, timeout_ms: s.timeout_ms || 10000 } };

