// Timeout o error de red: si la operación es sensible el resultado es INCIERTO (ASR-02)
const req = $('Solicitud del puerto').item.json;
const msg = $json.error?.message ?? String($json.error ?? 'error de red');
const status = req.sensitive === true ? 'UNKNOWN' : 'RETRYABLE_ERROR';
return { json: { status, data: null, error: { code: /timeout/i.test(msg) ? 'TIMEOUT' : 'NETWORK_ERROR', message: msg } } };

// Lee el cuerpo crudo y las cabeceras del webhook de Shopify (la firma se verifica en la base)
const item = $input.first();
let buf;
try { buf = await this.helpers.getBinaryDataBuffer(0, 'data'); } catch (e) { buf = Buffer.from(JSON.stringify(item.json.body || {}), 'utf8'); }
const h = item.json.headers || {};
return [{ json: {
  raw: buf.toString('utf8'),
  signature: h['x-shopify-hmac-sha256'] || null,
  topic: h['x-shopify-topic'] || null,
  webhook_id: h['x-shopify-webhook-id'] || null,
  shop: h['x-shopify-shop-domain'] || null,
  body: item.json.body || {}
} }];

// Normaliza el evento de Shopify al contrato sys.callback.v1 para SYS.03
const w = $('Leer cuerpo crudo').first().json;
const chk = $json.chk || {};
const topics = chk.settings?.topics || {};
const b = w.body || {};
const eventType = topics[w.topic] || ('unmapped.' + (w.topic || 'unknown'));
let payload;
if (eventType.startsWith('order.')) {
  const attr = (b.note_attributes || []).find(a => a.name === 'dalia_order_number');
  const tagNum = String(b.tags || '').split(',').map(t => t.trim()).find(t => t.startsWith('dalia-'));
  payload = { external_order_ref: b.admin_graphql_api_id || null, external_order_name: b.name || null, order_number: attr ? attr.value : (tagNum ? tagNum.slice(6) : null), financial_status: b.financial_status || null, fulfillment_status: b.fulfillment_status || null, cancelled_at: b.cancelled_at || null, updated_at: b.updated_at || null };
} else if (eventType.startsWith('inventory.')) {
  payload = { inventory_item_ref: b.inventory_item_id ? 'gid://shopify/InventoryItem/' + b.inventory_item_id : null, location_ref: b.location_id ? 'gid://shopify/Location/' + b.location_id : null, available: b.available ?? null, updated_at: b.updated_at || null };
} else if (eventType.startsWith('product.')) {
  payload = { product_ref: b.admin_graphql_api_id || (b.id ? 'gid://shopify/Product/' + b.id : null), updated_at: b.updated_at || null };
} else {
  payload = { topic: w.topic };
}
return [{ json: { source: 'commerce.shopify', external_event_id: w.webhook_id || ('sin-id-' + Date.now()), event_type: eventType, signature_valid: chk.signature_valid === true, payload, envelope: {} } }];

